1	/**
2	 * Rule-based comment redaction (ADR 0001, ADR 0009).
3	 * Runs at store time in the Submission Worker so that no raw comment is ever kept at rest.
4	 */
5	
6	export type RosterItem =
7	  | string
8	  | {
9	      readonly name?: string | null | undefined;
10	      readonly firstName?: string | null | undefined;
11	      readonly lastName?: string | null | undefined;
12	      readonly email?: string | null | undefined;
13	    };
14	
15	export type Roster = ReadonlyArray<RosterItem>;
16	
17	const URL_PATTERN = /(?:https?:\/\/|www\.)[^\s<>"'()[\]{},]+(?<![.,!?:;])/gi;
18	const EMAIL_PATTERN = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/gi;
19	const HANDLE_PATTERN = /(?:^|(?<=[^\w@]))@[A-Za-z0-9_]+(?=[^\w]|$)/g;
20	
21	// German numbers: +49 / 0049 / national 0, optional "(0)" trunk after +49, mobile 015x-017x or
22	// landline area code, then 1-6 digit groups with optional separators (space, -, /, " / ", " - ").
23	// Dots are not separators, so dates such as 12.11.2026 never match.
24	// Not preceded by a word character, "+" or digit; not followed by a word character or [.,]\d.
25	const GERMAN_PHONE_PATTERN =
26	  /(?<![\w+])(?:(?:\+|00)49[ /-]?(?:\(0\) ?)?|\(?0)(?:1[5-7]\d|[2-9]\d{1,4})\)?(?:(?: [-/] |[ /-])?\d{1,6}){1,6}(?!\w|[.,]\d)/g;
27	
28	// 7+ digits with common separators (+, -, ., space, parentheses, slash)
29	const PHONE_PATTERN =
30	  /(?:^|(?<=[^\w+]))(?<!\d[./-])((?:\+\d{1,4}[-.\s]?)?(?:\(?\d{2,5}\)?[-.\s]?)(?:\d{2,5}[-.\s]?){1,4}\d{2,5})(?=[^\w]|$)/g;
31	
32	// A date or year range at the start of a generic phone match: kept, and only the rest is checked
33	const DATE_OR_YEAR_RANGE_PREFIX =
34	  /^(?:\d{1,2}\.\d{1,2}\.(?:\d{4}|\d{2})|\d{4}-\d{1,2}-\d{1,2}|\d{1,2}\/\d{1,2}\/\d{2,4}|\d{4} ?[-–] ?\d{4})(?!\d)/;
35	
36	const PHONE_SEPARATOR = /[-.\s()+]/;
37	
38	// A lone digit and one space right before a phone match, e.g. the "0 " in "0 30 12 34 56"
39	const LONE_DIGIT_BEFORE = /(?:^|(?<=[^\w+.,]))\d $/;
40	
41	// Thousands-grouped amount: 1-3 leading digits, then groups of exactly 3 with one separator throughout
42	const THOUSANDS_GROUPED = /^[1-9]\d{0,2}([ \u00a0\u202f.,])\d{3}(?:\1\d{3})*$/;
43	
44	// Currency marker directly before an amount, with at most one space in between
45	const CURRENCY_BEFORE = /(?:[€$£]|(?<!\w)(?:EUR|USD|CHF|GBP)) ?$/i;
46	
47	// Optional decimal part, at most one space, then a currency marker as a symbol or a whole word
48	const CURRENCY_AFTER = /^(?:[.,]\d{1,2})? ?(?:[€$£]|Euros?|EUR|USD|Dollars?|CHF|Franken|GBP)(?!\w)/;
49	
50	// A phone cue right before a number ("Tel 612 345 678 Euro"): the number is never kept as an amount
51	const PHONE_CUE_BEFORE =
52	  /(?<!\w)(?:tel|telefon|phone|ruf|anrufen|call|fax|mobil|mobile|handy|nr|nummer|number)\.?:? ?(?:[€$£]|EUR|USD|CHF|GBP)? ?$/i;
53	
54	const isCurrencyAmount = (candidate: string, before: string, after: string): boolean =>
55	  THOUSANDS_GROUPED.test(candidate) &&
56	  !PHONE_CUE_BEFORE.test(before) &&
57	  (CURRENCY_BEFORE.test(before) || CURRENCY_AFTER.test(after));
58	
59	/**
60	 * Generic phone numbers: 7+ digits with separators. A match that starts with a date or a year
61	 * range keeps it, and the scan resumes right after it, so a number written after a date is still
62	 * caught. Never starts inside a number such as 1.2.2024.
63	 * A thousands-grouped amount next to a currency marker (€, $, EUR, Euro, ...) is kept. Without a
64	 * currency marker it is redacted: privacy beats false positives. A lone digit and a space right
65	 * before a redacted match is redacted with it.
66	 */
67	const redactGenericPhones = (text: string): string => {
68	  const pattern = new RegExp(PHONE_PATTERN.source, "g");
69	  let result = "";
70	  let kept = 0;
71	  for (let match = pattern.exec(text); match !== null; match = pattern.exec(text)) {
72	    const candidate = match[1] ?? "";
73	    const start = match.index + match[0].indexOf(candidate);
74	    const end = start + candidate.length;
75	    const date = DATE_OR_YEAR_RANGE_PREFIX.exec(candidate)?.[0];
76	    if (date !== undefined) {
77	      pattern.lastIndex = start + date.length;
78	    } else if (
79	      (candidate.match(/\d/g) ?? []).length >= 7 &&
80	      PHONE_SEPARATOR.test(candidate) &&
81	      !isCurrencyAmount(candidate, text.slice(0, start), text.slice(end))
82	    ) {
83	      // Absorb the lone digit only when it is not already part of kept text
84	      const lone = LONE_DIGIT_BEFORE.exec(text.slice(0, start));
85	      const from = lone !== null && start - 2 >= kept ? start - 2 : start;
86	      result += text.slice(kept, from) + "[phone]";
87	      kept = end;
88	    }
89	  }
90	  return result + text.slice(kept);
91	};
92	
93	const INTERNATIONAL_GERMAN_PREFIX = /^(?:\+|00)49/;
94	
95	// Significant national digits: without the +49/0049 prefix, the "(0)" trunk, or the national leading 0
96	const germanSignificantDigits = (match: string): number => {
97	  const international = INTERNATIONAL_GERMAN_PREFIX.test(match);
98	  const body = match.replace(INTERNATIONAL_GERMAN_PREFIX, "").replace("(0)", "");
99	  const digits = (body.match(/\d/g) ?? []).length;
100	  return international ? digits : digits - 1;
101	};
102	
103	const stripDiacritics = (text: string): string =>
104	  text
105	    .normalize("NFKD")
106	    .replace(/[\u0300-\u036f]/g, "")
107	    .toLowerCase();
108	
109	interface CandidateName {
110	  readonly norm: string;
111	  readonly words: ReadonlyArray<string>;
112	  readonly wordCount: number;
113	}
114	
115	const extractCandidateNames = (roster: Roster): ReadonlyArray<CandidateName> => {
116	  const rawNames = new Set<string>();
117	
118	  for (const item of roster) {
119	    if (typeof item === "string") {
120	      const trimmed = item.trim();
121	      if (trimmed.includes("@")) {
122	        const localPart = trimmed.split("@")[0] ?? "";
123	        if (localPart) {
124	          rawNames.add(localPart);
125	          for (const sub of localPart.split(/[._-]/)) {
126	            if (sub) rawNames.add(sub);
127	          }
128	        }
129	      } else {
130	        rawNames.add(trimmed);
131	        for (const sub of trimmed.split(/\s+/)) {
132	          if (sub) rawNames.add(sub);
133	        }
134	      }
135	    } else if (item && typeof item === "object") {
136	      if (item.name) {
137	        rawNames.add(item.name.trim());
138	        for (const sub of item.name.trim().split(/\s+/)) {
139	          if (sub) rawNames.add(sub);
140	        }
141	      }
142	      if (item.firstName) rawNames.add(item.firstName.trim());
143	      if (item.lastName) rawNames.add(item.lastName.trim());
144	      if (item.email) {
145	        const localPart = item.email.trim().split("@")[0] ?? "";
146	        if (localPart) {
147	          rawNames.add(localPart);
148	          for (const sub of localPart.split(/[._-]/)) {
149	            if (sub) rawNames.add(sub);
150	          }
151	        }
152	      }
153	    }
154	  }
155	
156	  const seen = new Set<string>();
157	  const candidates: Array<CandidateName> = [];
158	
159	  for (const name of rawNames) {
160	    const norm = stripDiacritics(name.trim());
161	    if (norm.length < 2 || seen.has(norm)) continue;
162	    seen.add(norm);
163	
164	    const words = norm.split(/\s+/).filter((w) => w.length > 0);
165	    if (words.length > 0) {
166	      candidates.push({
167	        norm,
168	        words,
169	        wordCount: words.length,
170	      });
171	    }
172	  }
173	
174	  // Greedy match: multi-word names first, then longer names
175	  return candidates.sort((a, b) => b.wordCount - a.wordCount || b.norm.length - a.norm.length);
176	};
177	
178	const redactNames = (text: string, candidates: ReadonlyArray<CandidateName>): string => {
179	  if (candidates.length === 0) return text;
180	
181	  const segmenter = new Intl.Segmenter("en", { granularity: "word" });
182	  const segments = [...segmenter.segment(text)];
183	
184	  let result = "";
185	  let i = 0;
186	
187	  while (i < segments.length) {
188	    const seg = segments[i];
189	    if (seg === undefined) break;
190	
191	    if (!seg.isWordLike) {
