/**
 * German phone numbers with 7-12 significant national digits are redacted. A longer match is two or
 * more numbers written next to each other: it is cut after the shortest prefix that ends before a
 * separator and has 7+ digits, and the rest is scanned again. Without such a prefix (an unseparated
 * run), the whole match is redacted: privacy beats false positives.
 */
const redactGermanPhones = (text: string): string => {
  const pattern = new RegExp(GERMAN_PHONE_PATTERN.source, "g");
  let result = "";
  let kept = 0;
  for (let match = pattern.exec(text); match !== null; match = pattern.exec(text)) {
    const start = match.index;
    const digits = germanSignificantDigits(match[0]);
    if (digits < 7) continue;
    let end = start + match[0].length;
    if (digits > 12) {
      // Groups are at most 6 digits, so the shortest such prefix has at most 12 significant digits
      for (let i = 1; i < match[0].length; i++) {
        if (PHONE_SPLIT_CHARACTER.test(match[0].charAt(i)) && germanSignificantDigits(match[0].slice(0, i)) >= 7) {
          end = start + i;
          pattern.lastIndex = end;
          break;
        }
      }
    }
    result += text.slice(kept, start) + "[phone]";
    kept = end;
  }
  return result + text.slice(kept);
};

